PredictedPathPostprocessorNode::PredictedPathPostprocessorNode(const rclcpp::NodeOptions & options)
: rclcpp::Node("predicted_path_postprocessor", options)
{
  auto processors = declare_parameter<std::vector<std::string>>("processors");
  context_ = std::make_unique<processor::Context>();
  processor_ = std::make_unique<processor::ComposableProcessor>(this, std::move(processors));

  stopwatch_ = std::make_unique<autoware_utils_system::StopWatch<std::chrono::milliseconds>>();
  stopwatch_->tic("cyclic_time");
  stopwatch_->tic("processing_time");
  debug_publisher_ = std::make_unique<autoware_utils_debug::DebugPublisher>(this, get_name());

  // NOTE: add additional subscriptions if needed, such as traffic light, etc.
  object_subscription_ = create_subscription<PredictedObjects>(
    "~/input/objects", rclcpp::QoS{1},
    [this, debug = declare_parameter<bool>("debug")](const PredictedObjects::ConstSharedPtr & msg) {
      this->stopwatch_->toc("processing_time", true);

      this->callback(msg, debug);  // main callback

      const auto cyclic_time = this->stopwatch_->toc("cyclic_time", true);
      const auto processing_time = this->stopwatch_->toc("processing_time", true);
      this->debug_publisher_->publish<Float64Stamped>("debug/cyclic_time_ms", cyclic_time);
      this->debug_publisher_->publish<Float64Stamped>("debug/processing_time_ms", processing_time);
    });

  lanelet_subscription_ = create_subscription<LaneletMapBin>(
    "~/input/lanelet_map", rclcpp::QoS{1}.transient_local(),
    [this](const LaneletMapBin::ConstSharedPtr & msg) { this->on_map(msg); });

  object_publisher_ = create_publisher<PredictedObjects>("~/output/objects", rclcpp::QoS{1});
}

void PredictedPathPostprocessorNode::callback(
  const PredictedObjects::ConstSharedPtr & msg, bool debug)
{
  auto objects = std::make_shared<PredictedObjects>(*msg);

  // update the context with the objects data
  context_->update(objects);

  if (debug) {
    const auto publish_reports = [this](const auto & reports) {
      for (const auto & [processor_name, report] : reports) {
        const auto topic_namespace = "debug/" + processor_name;

        debug_publisher_->publish<Float64Stamped>(
          topic_namespace + "/processing_time_ms", report.processing_time_ms);
        debug_publisher_->publish<PredictedObjects>(topic_namespace + "/objects", report.objects);
      }
    };

    const auto result = processor_->process_with_reports(objects, *context_);
    if (result) {
      const auto & [output, reports] = result.ok();
      object_publisher_->publish(output);
      publish_reports(reports);
    } else {
      RCLCPP_ERROR_STREAM(get_logger(), "Failed to process objects: " << result.err());
    }
  } else {
    const auto result = processor_->process(objects, *context_);
    if (result) {
      object_publisher_->publish(result.ok());
    } else {
      RCLCPP_ERROR_STREAM(get_logger(), "Failed to process objects: " << result.err());
    }
  }
}

ComposableProcessor::result_with_report_type ComposableProcessor::process_with_reports(
  const target_type::SharedPtr & objects, const Context & context) const
{
  return process_internal(objects, context, true);
}

ComposableProcessor::result_with_report_type ComposableProcessor::process_internal(
  const target_type::SharedPtr & objects, const Context & context, bool collect_intermediate) const
{
  std::unordered_map<std::string, std::pair<std::vector<double>, std::vector<PredictedObject>>>
    intermediates;
  if (collect_intermediate) {
    // Pre-allocate debug buffer for each processor
    for (const auto & processor : processors_) {
      intermediates[processor->name()].first.reserve(objects->objects.size());
      intermediates[processor->name()].second.reserve(objects->objects.size());
    }
  }

  std::vector<PredictedObject> processed_targets;
  processed_targets.reserve(objects->objects.size());

  for (auto & target : objects->objects) {
    for (const auto & processor : processors_) {
      if (collect_intermediate) {
        stopwatch_->toc("processing_time", true);
      }

      if (const auto result = processor->run(target, context); !result) {
        return make_err<output_with_report_type, error_type>(result.err());
      }

      if (collect_intermediate) {
        intermediates[processor->name()].first.push_back(stopwatch_->toc("processing_time", true));
        intermediates[processor->name()].second.push_back(target);
      }
    }
    processed_targets.push_back(std::move(target));
  }

  // build final output
  auto output = autoware_perception_msgs::build<target_type>()
                  .header(objects->header)
                  .objects(std::move(processed_targets));

  // build intermediate reports if needed
  report_type reports;
  if (collect_intermediate) {
    reports.reserve(processors_.size());
    for (const auto & [key, value] : intermediates) {
      const auto processing_time_ms = std::reduce(value.first.begin(), value.first.end());
      auto processed_target = autoware_perception_msgs::build<target_type>()
                                .header(objects->header)
                                .objects(value.second);
      reports.emplace(key, IntermediateReport{processing_time_ms, std::move(processed_target)});
    }
  }

  return make_ok<output_with_report_type, error_type>(std::move(output), std::move(reports));
}

result_type run(target_type & target, const Context & context)
{
  if (auto result = check_context(context); !result) {
    return result;
  }
  return process(target, context);
};

virtual result_type check_context(const Context &) const noexcept
{
  return make_ok<error_type>();
};

RefinePenetrationByStaticObjects::result_type RefinePenetrationByStaticObjects::process(
  target_type & target, const Context & context)
{
  const auto speed = std::abs(target.kinematics.initial_twist_with_covariance.twist.linear.x);

  for (size_t mode_index = 0; mode_index < target.kinematics.predicted_paths.size(); ++mode_index) {
    auto & mode = target.kinematics.predicted_paths[mode_index];
    const auto delta_t = rclcpp::Duration(mode.time_step).seconds();

    if (delta_t <= 0.0) {
      continue;
    }

    auto & waypoints = mode.path;
    if (waypoints.size() < 2) {
      continue;
    }

    const auto collision =
      find_collision(target, mode_index, context.as_objects()->objects, speed_threshold_);
    if (!collision) {
      continue;
    }

    // TODO(ktro2828): refactor interpolation
    // containers of values and keys
    constexpr double epsilon = 1e-6;
    std::vector<double> base_xs({waypoints[0].position.x});
    std::vector<double> base_ys({waypoints[0].position.y});
    std::vector<double> base_zs({waypoints[0].position.z});
    std::vector<double> base_keys({0.0});
    std::vector<double> query_keys({0.0});
    for (size_t i = 1; i < waypoints.size(); ++i) {
      const auto distance =
        autoware_utils_geometry::calc_distance2d(waypoints[i - 1], waypoints[i]);
      if (distance > epsilon) {
        base_xs.push_back(waypoints[i].position.x);
        base_ys.push_back(waypoints[i].position.y);
        base_zs.push_back(waypoints[i].position.z);
        base_keys.push_back(base_keys.back() + distance);
      }
      query_keys.push_back(query_keys.back() + speed * delta_t);
    }

    auto s_max = base_keys.back();
    // skip if the path is too short
    if (s_max < epsilon || base_keys.size() < 2) {
      continue;
    }

    s_max = std::clamp(collision->distance, 0.0, s_max);

    std::transform(
      query_keys.begin(), query_keys.end(), query_keys.begin(),
      [s_max](const auto & s) { return std::clamp(s, 0.0, s_max); });

    const auto query_xs = interpolator_(base_keys, base_xs, query_keys);
    const auto query_ys = interpolator_(base_keys, base_ys, query_keys);
    const auto query_zs = interpolator_(base_keys, base_zs, query_keys);

    // NOTE: waypoints[0] is the center position of the object, so we skip it
    for (size_t i = 1; i < waypoints.size(); ++i) {
      waypoints[i].position =
        autoware_utils_geometry::create_point(query_xs[i], query_ys[i], query_zs[i]);

      const auto yaw = autoware_utils_geometry::calc_azimuth_angle(
        waypoints[i - 1].position, waypoints[i].position);
      waypoints[i].orientation = autoware_utils_geometry::create_quaternion_from_yaw(yaw);
    }
  }

  return make_ok<error_type>();
}

std::optional<CollisionHit> find_collision(
  const autoware_perception_msgs::msg::PredictedObject & target, const size_t mode_index,
  const std::vector<autoware_perception_msgs::msg::PredictedObject> & obstacles,
  double speed_threshold)
{
  constexpr double epsilon = 1e-6;
  double min_collision_distance = std::numeric_limits<double>::infinity();
  double global_distance = 0.0;
  std::optional<CollisionHit> result = std::nullopt;
  const auto & mode = target.kinematics.predicted_paths[mode_index];
  for (size_t i = 0; i + 1 < mode.path.size(); ++i) {
    const auto & current = mode.path[i].position;
    const auto & next = mode.path[i + 1].position;

    const auto segment_length = std::hypot(next.x - current.x, next.y - current.y);
    if (segment_length < epsilon) {
      global_distance += segment_length;
      continue;
    }

    const auto target_obb = to_obb(mode.path, i, target.shape.dimensions);

    for (const auto & obstacle : obstacles) {
      // if the obstacle has a high speed or is the same as the path, skip it
      if (auto speed = std::abs(obstacle.kinematics.initial_twist_with_covariance.twist.linear.x);
          speed > speed_threshold || obstacle.object_id == target.object_id) {
        continue;
      }

      const auto obstacle_obb =
        to_obb(obstacle.kinematics.initial_pose_with_covariance.pose, obstacle.shape.dimensions);

      // check segment intersection: assumes the current global distance is the collision distance
      if (target_obb.overlaps(obstacle_obb)) {
        if (global_distance + epsilon < min_collision_distance) {
          min_collision_distance = global_distance;
          result.emplace(i, global_distance);
        }
      }
    }
    // accumulate global distance between current and next points
    global_distance += segment_length;
  }
  return result;
}

bodies::OBB to_obb(
  const geometry_msgs::msg::Pose & pose, const geometry_msgs::msg::Vector3 & extents)
{
  Eigen::Isometry3d pose_eigen;
  tf2::fromMsg(pose, pose_eigen);
  Eigen::Vector3d extents_eigen(extents.x, extents.y, extents.z);
  return bodies::OBB(pose_eigen, extents_eigen);
}

  interpolation_fn interpolator_;  //!< Interpolation function for path refinement.
};
