double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

const auto publish_reports = [this](const auto & reports) {
  for (const auto & [processor_name, report] : reports) {
    const auto topic_namespace = "debug/" + processor_name;

    debug_publisher_->publish<Float64Stamped>(
      topic_namespace + "/processing_time_ms", report.processing_time_ms);
    debug_publisher_->publish<PredictedObjects>(topic_namespace + "/objects", report.objects);
  }
};

ComposableProcessor::result_type ComposableProcessor::process(
  const target_type::SharedPtr & objects, const Context & context) const
{
  auto result = process_internal(objects, context, false);
  if (result) {
    auto [output, _] = result.ok();
    return make_ok<target_type, error_type>(std::move(output));
  } else {
    return make_err<target_type, error_type>(result.err());
  }
}

